const cl = (v, a, b) => Math.max(a, Math.min(b, v));

/* ── tube helper (gives lines real ~2.5px thickness) ─────────────────────── */
const _up = new THREE.Vector3(0, 1, 0);
function tube(a, b, mat, r) {
  const A = new THREE.Vector3(...a), B = new THREE.Vector3(...b);
  const dir = new THREE.Vector3().subVectors(B, A);
  const len = dir.length();
  const geo = new THREE.CylinderGeometry(r, r, len, 7, 1);
  const m = new THREE.Mesh(geo, mat);
  m.position.copy(A).addScaledVector(dir, 0.5);
  m.quaternion.setFromUnitVectors(_up, dir.clone().normalize());
  return m;
}

/* ── one camera glyph ────────────────────────────────────────────────────── */
function makeGlyph(color) {
  const g = new THREE.Group();
  const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 1 });
  const hw = RECT_W / 2, hh = RECT_H / 2;
  const TL = [-hw, RECT_CY + hh, 0], TR = [hw, RECT_CY + hh, 0];
  const BR = [hw, RECT_CY - hh, 0], BL = [-hw, RECT_CY - hh, 0];
  const bandY = RECT_CY - hh + 0.24;
  const BL2 = [-hw, bandY, 0], BR2 = [hw, bandY, 0];
  const C = [CX, CY, CZ];
  const segs = [
    [TL, TR], [TR, BR], [BR, BL], [BL, TL],   // image-plane rectangle
    [BL2, BR2],                               // inner band line
    [TL, BR], [TR, BL],                       // crossing diagonals
    [C, TL], [C, TR], [C, BL], [C, BR]        // edges from projection centre
  ];
  for (const [a, b] of segs) g.add(tube(a, b, mat, 0.018));
  const dot = new THREE.Mesh(new THREE.SphereGeometry(0.10, 18, 14), mat);
  dot.position.set(CX, CY, CZ);
  g.add(dot);
  g.userData.mat = mat;
  g.userData.setOpacity = (o) => { mat.opacity = o; };
  return g;
}

