  { title: 'The strip of camera poses', text: 'Five identical camera frusta sit in a row, each aiming away from you, linked by red arrows pointing right. Only the position changes — never the orientation.', mode: 'path', tx: -6 },
  { title: 'Slide the camera sideways', text: 'The active camera travels along the row while its optical axis stays fixed. The motion is purely perpendicular to the line of sight, so the forward velocity component is zero.', mode: 'path', tx: 0 },
  { title: 'What the image sees', text: 'In the projected view the scene points slide across the image plane opposite to the camera travel — the classic side-window sweep.', mode: 'flow', tx: 0 },
  { title: 'Near beats far: parallax', text: 'At full displacement the near point\'s flow vector is far longer than the far point\'s. Image shift scales as translation divided by depth: du = −f·Tx/Z.', mode: 'flow', tx: 6 }
];
let stepIdx = 0;
const stepTitle = document.getElementById('stepTitle');
const stepText = document.getElementById('stepText');
function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  playing = false; syncPlayBtn();
  setMode(s.mode);
  tween = { from: state.tx, to: s.tx, t: 0, dur: 1.0 };
  stepTitle.textContent = (stepIdx + 1) + '/' + STEPS.length + '  ' + s.title;
  stepText.textContent = s.text;
}
document.getElementById('stepPrev').addEventListener('click', () => goToStep(stepIdx - 1));
document.getElementById('stepNext').addEventListener('click', () => goToStep(stepIdx + 1));

document.getElementById('btnReset').style.display = '';

setMode('path');
setTx(-6);
goToStep(0);
tween = null;
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

