  Hover or click any frustum, arrow or scene point for an explanation. Drag to orbit out of the printed front view — the red arrows stay <b>inside the image plane</b>, so the forward velocity component is exactly zero. “Reset View” returns to the figure pose.
</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ── element spec (one line per drawn element) ───────────────────────────────
// image rectangle 1.70 x 0.76            → 4 CylinderGeometry tubes r=0.030, black
// inner band line (near image edge)      → 1 tube r=0.030, black
// 4 frustum edges apex→rect corners      → 4 tubes r=0.030, black  (cross as an X inside rect)
// projection centre (pinhole) dot        → SphereGeometry(0.11), black
// x5 identical glyphs at x = -6,-3,0,3,6 → Group copies, no rotation change
// 6 bold red arrows on the apex baseline → ShapeGeometry (shaft+head), 0xff0000
// translation axis through apexes        → dashed short tubes, slate (annotation)
// active camera glyph                    → same glyph, blue 0x1054a8 (movable)
// optical axis of active camera          → dashed tubes along -Z + ConeGeometry tip
// near / far scene points                → SphereGeometry(0.11) orange / blue
// projection rays point→pinhole          → THREE.Line, tinted
// image-plane overlay quad               → PlaneGeometry(1.7,0.76) white translucent
// projected image dots                   → SphereGeometry(0.05)
// image flow vectors                     → ShapeGeometry arrows, red
──────────────────────────────────────────────────────────────────────────── */

const BLACK = 0x000000, RED = 0xff0000, ACTIVE = 0x1054a8, SLATE = 0x5b7f9e;
const RECT_W = 1.70, RECT_H = 0.76, RECT_CY = 0.50;
const AP = new THREE.Vector3(0, -0.26, 0.50);   // pinhole / projection centre (glyph local)
const LINE_R = 0.030, DOT_R = 0.11;
const F = 1.4, S_DISP = 0.22, GAIN = 4.0;
const CAM_X = [-6, -3, 0, 3, 6];
const ARROW_X = [-7.5, -4.5, -1.5, 1.5, 4.5, 7.5];
const cl = (v, a, b) => Math.max(a, Math.min(b, v));

/* ── tube helper: gives "lines" the bold stroke weight of the printed figure ── */
const _up = new THREE.Vector3(0, 1, 0);
function tube(a, b, mat, r) {
  const A = new THREE.Vector3(...a), B = new THREE.Vector3(...b);
  const dir = new THREE.Vector3().subVectors(B, A);
  const len = Math.max(dir.length(), 1e-5);
  const m = new THREE.Mesh(new THREE.CylinderGeometry(r, r, len, 7, 1), mat);
  m.position.copy(A).addScaledVector(dir, 0.5);
  m.quaternion.setFromUnitVectors(_up, dir.clone().normalize());
  return m;
}

/* ── one camera glyph: rectangle + band + 4 edges to the pinhole + dot ─────── */
function makeGlyph(color) {
  const g = new THREE.Group();
  const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 1 });
  const hw = RECT_W / 2, hh = RECT_H / 2;
  const TL = [-hw, RECT_CY + hh, 0], TR = [hw, RECT_CY + hh, 0];
  const BR = [hw, RECT_CY - hh, 0], BL = [-hw, RECT_CY - hh, 0];
  const bandY = RECT_CY - hh + 0.19;
  const C = [AP.x, AP.y, AP.z];
  const segs = [
    [TL, TR], [TR, BR], [BR, BL], [BL, TL],              // image rectangle
    [[-hw, bandY, 0], [hw, bandY, 0]],                   // inner band line
    [C, TL], [C, TR], [C, BL], [C, BR]                   // frustum edges (cross as an X)
  ];
  for (const [a, b] of segs) g.add(tube(a, b, mat, LINE_R));
  const dot = new THREE.Mesh(new THREE.SphereGeometry(DOT_R, 18, 14), mat);
  dot.position.copy(AP);
  g.add(dot);
  g.userData.mat = mat;
  return g;
}

/* ── the five printed frusta ─────────────────────────────────────────────── */
const stripGroup = new THREE.Group();
scene.add(stripGroup);
const glyphs = CAM_X.map((x) => {
  const g = makeGlyph(BLACK);
  g.position.set(x, 0, 0);
  stripGroup.add(g);
  registerInteractive(g, {
    title: 'Camera pose at X = ' + x,
    tooltip: 'Same camera, shifted sideways',
    body: 'All five frusta are the SAME camera drawn at successive instants: identical size, identical orientation, identical optical axis (pointing away from you). Only the position along X changes, so the whole motion lies inside the image plane.'
  });
  return g;
});

/* ── six bold red arrows on the pinhole baseline ─────────────────────────── */
function arrowGeom(len, th, headLen, headW, dir) {
  const d = dir < 0 ? -1 : 1;
  const hx = d * (len - headLen), tip = d * len;
  const s = new THREE.Shape();
  s.moveTo(0, -th / 2); s.lineTo(hx, -th / 2); s.lineTo(hx, -headW / 2);
  s.lineTo(tip, 0);
  s.lineTo(hx, headW / 2); s.lineTo(hx, th / 2); s.lineTo(0, th / 2);
  s.closePath();
  return new THREE.ShapeGeometry(s);
}
const redMat = new THREE.MeshBasicMaterial({ color: RED, side: THREE.DoubleSide, transparent: true, opacity: 1 });
const arrowsGroup = new THREE.Group();
scene.add(arrowsGroup);
for (const cx of ARROW_X) {
  const L = 1.8;
  const geo = arrowGeom(L, 0.24, 0.50, 0.58, 1);
  geo.translate(-L / 2, 0, 0);
  const m = new THREE.Mesh(geo, redMat);
  m.position.set(cx, AP.y, AP.z);            // coplanar with the pinhole baseline
  arrowsGroup.add(m);
  registerInteractive(m, {
    title: 'Translation direction T',
    tooltip: 'Pure sideways translation',
    body: 'The red arrows are the camera velocity T: purely horizontal and parallel to the image plane. Because T is perpendicular to the optical axis, the forward (depth) component is zero — the scene sweeps sideways, as seen through a car side window.'
  });
}

/* ── annotation: dashed translation axis through the pinholes ────────────── */
const slateMat = new THREE.MeshBasicMaterial({ color: SLATE, transparent: true, opacity: 0.85 });
const trail = new THREE.Group();
scene.add(trail);
for (let x = -6.9; x < 6.9; x += 0.40) {
  trail.add(tube([x, AP.y, AP.z], [Math.min(x + 0.22, 6.9), AP.y, AP.z], slateMat, 0.012));
}

/* ── the movable (active) camera ─────────────────────────────────────────── */
const activeGroup = new THREE.Group();
scene.add(activeGroup);
const activeGlyph = makeGlyph(ACTIVE);
activeGroup.add(activeGlyph);
registerInteractive(activeGlyph, {
  title: 'Active camera',
  tooltip: 'Drag the slider to translate it',
  body: 'This is the camera you control. Its orientation is locked; only X changes. The dashed optical axis stays parallel to itself — a pure translation, no rotation.'
});

const axisGroup = new THREE.Group();
activeGroup.add(axisGroup);
const axisMat = new THREE.MeshBasicMaterial({ color: SLATE, transparent: true, opacity: 0.9 });
for (let z = 0; z > -2.3; z -= 0.34) {
  axisGroup.add(tube([AP.x, AP.y, AP.z + z], [AP.x, AP.y, AP.z + Math.max(z - 0.20, -2.3)], axisMat, 0.013));
}
const axisTip = new THREE.Mesh(new THREE.ConeGeometry(0.075, 0.22, 14), axisMat);
axisTip.position.set(AP.x, AP.y, AP.z - 2.42);
axisTip.rotation.x = -Math.PI / 2;
axisGroup.add(axisTip);

/* image-plane overlay (flow view) */
const imgOverlay = new THREE.Group();
imgOverlay.visible = false;
activeGroup.add(imgOverlay);
const quad = new THREE.Mesh(
  new THREE.PlaneGeometry(RECT_W, RECT_H),
  new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.9, side: THREE.DoubleSide, depthWrite: false })
);
quad.position.set(0, RECT_CY, 0.004);
imgOverlay.add(quad);

/* ── scene points, rays, projected dots, flow vectors ────────────────────── */
const PTS = [
  { P: new THREE.Vector3(1.2, 0.55, -2.0), color: 0xe07a00, name: 'near' },
  { P: new THREE.Vector3(-0.9, 0.95, -7.0), color: 0x1b7fc4, name: 'far' }
];
const flowGroup = new THREE.Group();
for (const q of PTS) {
  q.Zd = AP.z - q.P.z;
  q.flowPerUnit = F / q.Zd;
  const mat = new THREE.MeshBasicMaterial({ color: q.color });
  const sph = new THREE.Mesh(new THREE.SphereGeometry(0.11, 16, 12), mat);
  sph.position.copy(q.P);
  flowGroup.add(sph);
  registerInteractive(sph, {
    title: (q.name === 'near' ? 'Near scene point  (Z ≈ 2.5)' : 'Far scene point  (Z ≈ 7.5)'),
    tooltip: 'Depth Z sets how fast it sweeps',
    body: 'For a pure lateral translation Tx the image point shifts by du = −f·Tx / Z. This point sits at Z ≈ ' +
      q.Zd.toFixed(1) + ', so it slides ' + (q.name === 'near' ? '3× faster' : '3× slower') +
      ' across the image than the other one. That depth-dependent difference is motion parallax.'
  });

  const ray = new THREE.Line(
    new THREE.BufferGeometry().setFromPoints([q.P.clone(), q.P.clone()]),
    new THREE.LineBasicMaterial({ color: q.color, transparent: true, opacity: 0.6 })
  );
  flowGroup.add(ray);
  q.ray = ray;

  const dot = new THREE.Mesh(new THREE.SphereGeometry(0.05, 14, 10), mat);
  imgOverlay.add(dot);
  q.dot = dot;

  const len = GAIN * F * S_DISP / q.Zd;
  const hl = Math.min(0.13, len * 0.45);
  const am = new THREE.Mesh(arrowGeom(len, 0.045, hl, hl * 1.2, -1),
    new THREE.MeshBasicMaterial({ color: RED, side: THREE.DoubleSide }));
  imgOverlay.add(am);
  q.arrow = am;
}

/* ── CAMERA: the printed, front-on figure pose ───────────────────────────── */
const FRONT_VIEW = { projection: 'orthographic', azimuthDeg: 90, elevationDeg: 0, heightFraction: 0.93 };
const FLOW_VIEW = { projection: 'orthographic', azimuthDeg: 101, elevationDeg: 13, zoom: 0.72 };
setCameraView(FRONT_VIEW);

/* ── LABELS ──────────────────────────────────────────────────────────────── */
const tickLabels = CAM_X.map(x =>
  addLabel('X = ' + x, new THREE.Vector3(x, RECT_CY + RECT_H / 2 + 0.16, 0),
    { fontSize: '10px', color: '#777' }));

const lblT = addLabel('translation&nbsp;<b>T</b>&nbsp; ∥ image plane &nbsp;( ⊥ optical axis )',
  new THREE.Vector3(0, -1.05, AP.z), { fontSize: '12px', color: '#c00000' });

const lblActive = addLabel('active camera', new THREE.Vector3(-6, 1.55, 0),
  { fontSize: '11px', color: '#1054a8', bold: true });
const lblAxis = addLabel('optical axis', new THREE.Vector3(-6, -0.26, -1.9),
  { fontSize: '11px', color: '#42708f', offset: [0, 14] });

const lblImg = addLabel('image plane', new THREE.Vector3(-6, 1.15, 0.02), { fontSize: '10px', color: '#444' });
const lblNear = addLabel('near point&nbsp; Z ≈ 2.5', PTS[0].P.clone().add(new THREE.Vector3(0, 0.3, 0)),
  { fontSize: '11px', color: '#b05e00' });
const lblFar = addLabel('far point&nbsp; Z ≈ 7.5', PTS[1].P.clone().add(new THREE.Vector3(0, 0.32, 0)),
  { fontSize: '11px', color: '#14618f' });
const lblNearFlow = addLabel('', new THREE.Vector3(), { fontSize: '10px', color: '#c00000' });
const lblFarFlow = addLabel('', new THREE.Vector3(), { fontSize: '10px', color: '#c00000' });
const flowLabels = [lblImg, lblNear, lblFar, lblNearFlow, lblFarFlow];
function setLblVis(e, on) { e.div.style.visibility = on ? 'visible' : 'hidden'; }

/* ── STATE ───────────────────────────────────────────────────────────────── */
const state = { tx: -6, mode: 'path', annot: false, active: false };
const slider = document.getElementById('slideCamera');
const txVal = document.getElementById('txVal');
const readout = document.getElementById('flowReadout');
const chkAnnot = document.getElementById('chkAnnot');
const btnPath = document.getElementById('modePath');
const btnFlow = document.getElementById('modeFlow');
let flowPanX = 0;

function applyVis() {
  const flow = state.mode === 'flow';
  trail.visible = state.annot;
  axisGroup.visible = state.annot;
  activeGroup.visible = state.active;
  imgOverlay.visible = flow && state.active;
  tickLabels.forEach(l => setLblVis(l, state.annot));
  setLblVis(lblT, !flow);
  setLblVis(lblActive, state.active && state.annot);
  setLblVis(lblAxis, state.active && state.annot);
  flowLabels.forEach(l => setLblVis(l, flow && state.active));
  glyphs.forEach(g => { g.userData.mat.opacity = flow ? 0.16 : 1; });
  redMat.opacity = flow ? 0.20 : 1;
  slateMat.opacity = flow ? 0.35 : 0.85;
}

function updateFlow() {
  const tx = state.tx;
  const Cw = new THREE.Vector3(tx + AP.x, AP.y, AP.z);
  let txt = '';
  for (const q of PTS) {
    const u = F * (q.P.x - Cw.x) / q.Zd;
    const v = F * (q.P.y - Cw.y) / q.Zd;
    const lx = cl(u * S_DISP, -0.78, 0.78);
    const ly = RECT_CY + cl(v * S_DISP, -0.33, 0.33);
    q.dot.position.set(lx, ly, 0.02);
    q.arrow.position.set(lx, ly, 0.03);
    q.ray.geometry.setFromPoints([q.P.clone(), Cw.clone()]);
    q.ray.geometry.computeBoundingSphere();
    const lbl = (q.name === 'near') ? lblNearFlow : lblFarFlow;
    lbl.pos.set(tx + lx - GAIN * F * S_DISP / q.Zd - 0.20, ly - 0.16, 0.06);
    lbl.div.innerHTML = '|du| = ' + q.flowPerUnit.toFixed(3) + ' /unit';
    txt += (q.name === 'near' ? 'near' : 'far&nbsp;') + ' (Z=' + q.Zd.toFixed(1) + '): u = ' +
      u.toFixed(3) + ', |du/dT| = ' + q.flowPerUnit.toFixed(3) + '<br>';
  }
  if (state.mode === 'flow') {
    const ratio = PTS[0].flowPerUnit / PTS[1].flowPerUnit;
    readout.innerHTML = '<b>du = &minus;f·T<sub>x</sub>/Z</b> &nbsp;(f = ' + F + ')<br>' + txt +
      '<b>near / far = ' + ratio.toFixed(1) + '×</b> — pure parallax, no looming.';
  }
}

function flowFollow() {
  if (state.mode !== 'flow') return;
  const want = 0.55 * state.tx;
  const dx = want - flowPanX;
  if (Math.abs(dx) < 1e-6) return;
  camera.position.x += dx;
  controls.target.x += dx;
  flowPanX = want;
  controls.update();
}

function setTx(v, silent) {
  state.tx = cl(v, -6, 6);
  activeGroup.position.x = state.tx;
  slider.value = state.tx;
  txVal.textContent = state.tx.toFixed(1);
  lblActive.pos.set(state.tx, 1.55, 0);
  lblAxis.pos.set(state.tx + 0.35, -0.30, -1.9);
  lblImg.pos.set(state.tx - 0.60, RECT_CY + RECT_H / 2 + 0.20, 0.02);
  updateFlow();
  flowFollow();
  if (!silent && !state.active) { state.active = true; applyVis(); }
}

function setMode(m) {
  const changed = state.mode !== m;
  state.mode = m;
  const flow = (m === 'flow');
  if (flow && !flowGroup.parent) scene.add(flowGroup);
  if (!flow && flowGroup.parent) scene.remove(flowGroup);
  if (flow) state.active = true;
  btnPath.classList.toggle('active', !flow);
  btnFlow.classList.toggle('active', flow);
  applyVis();
  if (changed || !flow) {
    if (flow) {
      flowPanX = 0.55 * state.tx;
      setCameraView({ ...FLOW_VIEW, target: [flowPanX, 0.1, -1.4] });
    } else {
      flowPanX = 0;
      setCameraView(FRONT_VIEW);
    }
  }
  if (!flow) readout.innerHTML = 'Front-on <b>figure view</b>. Switch to <i>Projected optical flow</i> to see how the image moves.';
  updateFlow();
}

slider.addEventListener('input', () => {
  playing = false; tween = null; syncPlayBtn();
  setTx(parseFloat(slider.value));
});
btnPath.addEventListener('click', () => setMode('path'));
btnFlow.addEventListener('click', () => setMode('flow'));
chkAnnot.addEventListener('change', () => { state.annot = chkAnnot.checked; applyVis(); });

/* ── animation ───────────────────────────────────────────────────────────── */
let playing = false, tween = null, last = performance.now();
const btnPlay = document.getElementById('playTranslation');
function syncPlayBtn() {
  btnPlay.textContent = playing ? '❚❚ Pause' : '▶ Play lateral translation';
  btnPlay.classList.toggle('active', playing);
}
btnPlay.addEventListener('click', () => {
  playing = !playing; tween = null; syncPlayBtn();
  if (playing && !state.active) { state.active = true; applyVis(); }
});

function tick() {
  requestAnimationFrame(tick);
  const now = performance.now();
  const dt = Math.min(0.05, (now - last) / 1000); last = now;
  if (playing) {
    let v = state.tx + 2.0 * dt;
    if (v > 6) v = -6;
    setTx(v, true);
  } else if (tween) {
    tween.t += dt;
    const k = Math.min(1, tween.t / tween.dur);
    const e = k * k * (3 - 2 * k);
    setTx(tween.from + (tween.to - tween.from) * e, true);
    if (k >= 1) tween = null;
  }
}
tick();

/* ── guided demo ─────────────────────────────────────────────────────────── */
const STEPS = [
  {
    title: 'The printed figure', mode: 'path', tx: -6, annot: false, active: false,
    text: 'Five identical camera frusta in a row, each aiming away from you, separated by bold red arrows pointing right. Only the position changes — never the orientation, never the size.'
  },
  {
    title: 'One camera, five instants', mode: 'path', tx: -3, annot: true, active: true,
    text: 'The blue camera is the one you control. Its dashed optical axis points into the page and stays parallel to itself as it slides: rotation is exactly zero.'
  },
  {
    title: 'T lies in the image plane', mode: 'path', tx: 6, annot: true, active: true,
    text: 'The red arrows are perpendicular to every optical axis, so the forward velocity component Tz = 0. This is the "side-window" motion, not a zoom-in.'
  },
  {
    title: 'What the image sees', mode: 'flow', tx: -3, annot: false, active: true,
    text: 'Rays from two scene points meet at the pinhole. On the image plane both points slide opposite to the camera travel — the classic sideways sweep.'
  },
  {
    title: 'Near beats far: parallax', mode: 'flow', tx: 3, annot: false, active: true,
    text: 'The near point\'s flow vector is three times longer than the far point\'s: image shift is translation divided by depth, du = −f·Tx / Z. Lateral motion therefore reveals depth.'
  }
];
let stepIdx = 0;
const stepTitle = document.getElementById('stepTitle');
const stepText = document.getElementById('stepText');
function goToStep(i, animate) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  playing = false; syncPlayBtn();
  state.annot = s.annot; chkAnnot.checked = s.annot;
  state.active = s.active;
  setMode(s.mode);
  applyVis();
  if (animate) { tween = { from: state.tx, to: s.tx, t: 0, dur: 1.0 }; }
  else { tween = null; setTx(s.tx, true); }
  stepTitle.textContent = (stepIdx + 1) + '/' + STEPS.length + '  ' + s.title;
  stepText.textContent = s.text;
}
document.getElementById('stepPrev').addEventListener('click', () => goToStep(stepIdx - 1, true));
document.getElementById('stepNext').addEventListener('click', () => goToStep(stepIdx + 1, true));

document.getElementById('btnReset').style.display = '';

/* ── initial state = the printed figure ──────────────────────────────────── */
goToStep(0, false);
// @FIGURE_CODE_END

