    const ratio = PTS[0].flowPerUnit / PTS[1].flowPerUnit;
    readout.innerHTML = '<b>du = &minus;f·T<sub>x</sub>/Z</b> &nbsp;(f = ' + F + ')<br>' + txt +
      '<b>near / far = ' + ratio.toFixed(1) + '×</b> — pure parallax, no looming.';
  }
}

function flowFollow() {
  if (state.mode !== 'flow') return;
  const want = 0.55 * state.tx;
  const dx = want - flowPanX;
  if (Math.abs(dx) < 1e-6) return;
  camera.position.x += dx;
  controls.target.x += dx;
  flowPanX = want;
  controls.update();
}

function setTx(v, silent) {
  state.tx = cl(v, -6, 6);
  activeGroup.position.x = state.tx;
  slider.value = state.tx;
  txVal.textContent = state.tx.toFixed(1);
  lblActive.pos.set(state.tx, 1.55, 0);
  lblAxis.pos.set(state.tx + 0.35, -0.30, -1.9);
  lblImg.pos.set(state.tx - 0.60, RECT_CY + RECT_H / 2 + 0.20, 0.02);
  updateFlow();
  flowFollow();
  if (!silent && !state.active) { state.active = true; applyVis(); }
}

function setMode(m) {
  const changed = state.mode !== m;
  state.mode = m;
  const flow = (m === 'flow');
  if (flow && !flowGroup.parent) scene.add(flowGroup);
  if (!flow && flowGroup.parent) scene.remove(flowGroup);
  if (flow) state.active = true;
  btnPath.classList.toggle('active', !flow);
  btnFlow.classList.toggle('active', flow);
  applyVis();
  if (changed || !flow) {
    if (flow) {
      flowPanX = 0.55 * state.tx;
      setCameraView({ ...FLOW_VIEW, target: [flowPanX, 0.1, -1.4] });
    } else {
      flowPanX = 0;
      setCameraView(FRONT_VIEW);
    }
  }
  if (!flow) readout.innerHTML = 'Front-on <b>figure view</b>. Switch to <i>Projected optical flow</i> to see how the image moves.';
  updateFlow();
}

slider.addEventListener('input', () => {
  playing = false; tween = null; syncPlayBtn();
  setTx(parseFloat(slider.value));
});
btnPath.addEventListener('click', () => setMode('path'));
btnFlow.addEventListener('click', () => setMode('flow'));
chkAnnot.addEventListener('change', () => { state.annot = chkAnnot.checked; applyVis(); });

/* ── animation ───────────────────────────────────────────────────────────── */
let playing = false, tween = null, last = performance.now();
const btnPlay = document.getElementById('playTranslation');
function syncPlayBtn() {
  btnPlay.textContent = playing ? '❚❚ Pause' : '▶ Play lateral translation';
  btnPlay.classList.toggle('active', playing);
}
btnPlay.addEventListener('click', () => {
  playing = !playing; tween = null; syncPlayBtn();
  if (playing && !state.active) { state.active = true; applyVis(); }
});

function tick() {
  requestAnimationFrame(tick);
  const now = performance.now();
  const dt = Math.min(0.05, (now - last) / 1000); last = now;
  if (playing) {
    let v = state.tx + 2.0 * dt;
    if (v > 6) v = -6;
    setTx(v, true);
  } else if (tween) {
    tween.t += dt;
    const k = Math.min(1, tween.t / tween.dur);
    const e = k * k * (3 - 2 * k);
    setTx(tween.from + (tween.to - tween.from) * e, true);
    if (k >= 1) tween = null;
  }
}
tick();

/* ── guided demo ─────────────────────────────────────────────────────────── */
const STEPS = [
  {
    title: 'The printed figure', mode: 'path', tx: -6, annot: false, active: false,
    text: 'Five identical camera frusta in a row, each aiming away from you, separated by bold red arrows pointing right. Only the position changes — never the orientation, never the size.'
  },
  {
    title: 'One camera, five instants', mode: 'path', tx: -3, annot: true, active: true,
    text: 'The blue camera is the one you control. Its dashed optical axis points into the page and stays parallel to itself as it slides: rotation is exactly zero.'
  },
  {
    title: 'T lies in the image plane', mode: 'path', tx: 6, annot: true, active: true,
    text: 'The red arrows are perpendicular to every optical axis, so the forward velocity component Tz = 0. This is the "side-window" motion, not a zoom-in.'
  },
  {
    title: 'What the image sees', mode: 'flow', tx: -3, annot: false, active: true,
    text: 'Rays from two scene points meet at the pinhole. On the image plane both points slide opposite to the camera travel — the classic sideways sweep.'
  },
  {
    title: 'Near beats far: parallax', mode: 'flow', tx: 3, annot: false, active: true,
    text: 'The near point\'s flow vector is three times longer than the far point\'s: image shift is translation divided by depth, du = −f·Tx / Z. Lateral motion therefore reveals depth.'
  }
];
let stepIdx = 0;
const stepTitle = document.getElementById('stepTitle');
const stepText = document.getElementById('stepText');
function goToStep(i, animate) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  playing = false; syncPlayBtn();
  state.annot = s.annot; chkAnnot.checked = s.annot;
  state.active = s.active;
  setMode(s.mode);
  applyVis();
  if (animate) { tween = { from: state.tx, to: s.tx, t: 0, dur: 1.0 }; }
  else { tween = null; setTx(s.tx, true); }
  stepTitle.textContent = (stepIdx + 1) + '/' + STEPS.length + '  ' + s.title;
  stepText.textContent = s.text;
}
document.getElementById('stepPrev').addEventListener('click', () => goToStep(stepIdx - 1, true));
document.getElementById('stepNext').addEventListener('click', () => goToStep(stepIdx + 1, true));

document.getElementById('btnReset').style.display = '';

/* ── initial state = the printed figure ──────────────────────────────────── */
goToStep(0, false);
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<div style="font-weight:bold;font-size:12px">Camera translating sideways</div>
<div style="font-size:11px;color:#444;line-height:1.35">
  Five copies of the <i>same</i> camera, shifted along X. Red arrows = translation <b>T</b>, always parallel to the image plane.
