<div style="font-size:10px;color:#666;border-top:1px solid #ddd;margin-top:5px;padding-top:5px">
  Hover or click any frustum, arrow or scene point for an explanation. Drag to orbit out of the printed front view — the red arrows stay <b>inside the image plane</b>, so the forward velocity component is exactly zero. “Reset View” returns to the figure pose.
</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ── element spec (one line per drawn element) ───────────────────────────────
// image rectangle 0.325 x 0.133           → 4 CylinderGeometry tubes r=0.0042, black
// inner band line (two-tier box)          → 1 tube r=0.0042, black, 0.042 above bottom edge
// outer frustum edges apex→flared corners → 2 tubes, tops 0.022 OUTSIDE the bottom corners
// inner frustum edges apex→top corners    → 2 tubes crossing the box as a V
// pinhole (projection centre)             → SphereGeometry(0.020), black
// x5 identical glyphs, spacing 0.78       → Group copies, identical orientation
// 6 bold red arrows on the pinhole line   → ShapeGeometry (shaft+head), 0xff0000, len 0.32
// translation axis through the pinholes   → dashed short tubes, slate (annotation)
// active camera glyph                     → same glyph, blue 0x1054a8 (movable)
// optical axis of active camera           → dashed tubes along -Z + ConeGeometry tip
// near / far scene points                 → SphereGeometry(0.022) orange / blue
// projection rays point→pinhole           → THREE.Line, tinted
// image-plane overlay quad                → PlaneGeometry(0.325,0.133) white translucent
// projected image dots                    → SphereGeometry(0.010)
// image flow vectors                      → ShapeGeometry arrows, red, length ∝ 1/Z
──────────────────────────────────────────────────────────────────────────── */

const BLACK = 0x000000, RED = 0xff0000, ACTIVE = 0x1054a8, SLATE = 0x5b7f9e;

const SPACING = 0.78;                       // baseline between camera poses
const RECT_W = 0.325, RECT_H = 0.133;       // image rectangle
const BOT_Y = 0.085;                        // rectangle bottom edge above the pinhole
const TOP_Y = BOT_Y + RECT_H;
const MID_Y = BOT_Y + RECT_H / 2;
const BAND_Y = BOT_Y + 0.042;               // inner band line, clearly off the bottom edge
const FLARE = 0.022;                        // frustum edges pass OUTSIDE the bottom corners
const LINE_R = 0.0042, DOT_R = 0.020;
const ARROW_L = 0.32, ARROW_TH = 0.038, ARROW_HL = 0.095, ARROW_HW = 0.108;
const CAM_I = [-2, -1, 0, 1, 2];
const CAM_X = CAM_I.map(i => i * SPACING);
const ARROW_X = [-2.5, -1.5, -0.5, 0.5, 1.5, 2.5].map(i => i * SPACING);
const F = 0.08;                             // focal length (world units)
const FLOW_K = 0.09;                        // flow-arrow length scale
const cl = (v, a, b) => Math.max(a, Math.min(b, v));

/* ── tube helper: gives "lines" the bold stroke weight of the printed figure ── */
const _up = new THREE.Vector3(0, 1, 0);
function tube(a, b, mat, r) {
  const A = new THREE.Vector3(a[0], a[1], a[2] || 0);
  const B = new THREE.Vector3(b[0], b[1], b[2] || 0);
  const dir = new THREE.Vector3().subVectors(B, A);
  const len = Math.max(dir.length(), 1e-6);
  const m = new THREE.Mesh(new THREE.CylinderGeometry(r, r, len, 8, 1), mat);
  m.position.copy(A).addScaledVector(dir, 0.5);
  m.quaternion.setFromUnitVectors(_up, dir.clone().normalize());
  return m;
}

/* ── one camera glyph: two-tier box + flared frustum + pinhole dot ───────── */
function makeGlyph(color) {
  const g = new THREE.Group();
  const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 1 });
  const hw = RECT_W / 2, fx = hw + FLARE;
  const AP = [0, 0, 0];
  const segs = [
    [[-hw, TOP_Y], [hw, TOP_Y]],           // image rectangle: top
    [[hw, TOP_Y], [hw, BOT_Y]],            // right
    [[hw, BOT_Y], [-hw, BOT_Y]],           // bottom
    [[-hw, BOT_Y], [-hw, TOP_Y]],          // left
    [[-hw, BAND_Y], [hw, BAND_Y]],         // inner band (two-tier box)
    [AP, [-fx, BOT_Y]],                    // flared outer edge, left
    [AP, [fx, BOT_Y]],                     // flared outer edge, right
    [AP, [-hw, TOP_Y]],                    // inner edge to top-left corner
    [AP, [hw, TOP_Y]]                      // inner edge to top-right corner
  ];
  for (const [a, b] of segs) g.add(tube(a, b, mat, LINE_R));
  const dot = new THREE.Mesh(new THREE.SphereGeometry(DOT_R, 18, 14), mat);
  dot.position.set(0, 0, 0);
  g.add(dot);
  g.userData.mat = mat;
  return g;
}

/* ── the five printed frusta ─────────────────────────────────────────────── */
const stripGroup = new THREE.Group();
scene.add(stripGroup);
const glyphs = CAM_X.map((x, k) => {
  const g = makeGlyph(BLACK);
  g.position.set(x, 0, 0);
  stripGroup.add(g);
  registerInteractive(g, {
    title: 'Camera pose ' + (CAM_I[k] >= 0 ? '+' : '') + CAM_I[k] + ' baselines',
    tooltip: 'Same camera, shifted sideways',
    body: 'All five frusta are the SAME camera drawn at successive instants: identical size, identical orientation, identical optical axis (pointing away from you). Only the position along X changes, so the whole motion lies inside the image plane.'
  });
  return g;
});

/* ── six bold red arrows on the pinhole baseline ─────────────────────────── */
function arrowGeom(len, th, headLen, headW, dir) {
  const d = dir < 0 ? -1 : 1;
  const hx = d * (len - headLen), tip = d * len;
  const s = new THREE.Shape();
  s.moveTo(0, -th / 2); s.lineTo(hx, -th / 2); s.lineTo(hx, -headW / 2);
  s.lineTo(tip, 0);
  s.lineTo(hx, headW / 2); s.lineTo(hx, th / 2); s.lineTo(0, th / 2);
  s.closePath();
  return new THREE.ShapeGeometry(s);
}
const redMat = new THREE.MeshBasicMaterial({ color: RED, side: THREE.DoubleSide, transparent: true, opacity: 1 });
const arrowsGroup = new THREE.Group();
scene.add(arrowsGroup);
for (const cx of ARROW_X) {
  const geo = arrowGeom(ARROW_L, ARROW_TH, ARROW_HL, ARROW_HW, 1);
  geo.translate(-ARROW_L / 2, 0, 0);
  const m = new THREE.Mesh(geo, redMat);
  m.position.set(cx, 0, 0);                 // coplanar with the pinhole baseline
  arrowsGroup.add(m);
  registerInteractive(m, {
    title: 'Translation direction T',
    tooltip: 'Pure sideways translation',
    body: 'The red arrows are the camera velocity T: purely horizontal and parallel to the image plane. Because T is perpendicular to the optical axis, the forward (depth) component is zero — the scene sweeps sideways, as seen through a car side window.'
  });
}

/* ── annotation: dashed translation axis through the pinholes ────────────── */
const slateMat = new THREE.MeshBasicMaterial({ color: SLATE, transparent: true, opacity: 0.85 });
const trail = new THREE.Group();
scene.add(trail);
for (let x = -2.05; x < 2.05; x += 0.10) {
  trail.add(tube([x, 0, 0], [Math.min(x + 0.055, 2.05), 0, 0], slateMat, 0.0026));
}

/* ── the movable (active) camera ─────────────────────────────────────────── */
const activeGroup = new THREE.Group();
scene.add(activeGroup);
const activeGlyph = makeGlyph(ACTIVE);
activeGroup.add(activeGlyph);
registerInteractive(activeGlyph, {
  title: 'Active camera',
  tooltip: 'Drag the slider to translate it',
  body: 'This is the camera you control. Its orientation is locked; only X changes. The dashed optical axis stays parallel to itself — a pure translation, no rotation.'
});

const axisGroup = new THREE.Group();
activeGroup.add(axisGroup);
const axisMat = new THREE.MeshBasicMaterial({ color: SLATE, transparent: true, opacity: 0.9 });
for (let z = 0; z > -0.56; z -= 0.085) {
  axisGroup.add(tube([0, 0, z], [0, 0, Math.max(z - 0.050, -0.56)], axisMat, 0.0028));
}
const axisTip = new THREE.Mesh(new THREE.ConeGeometry(0.018, 0.055, 14), axisMat);
axisTip.position.set(0, 0, -0.60);
axisTip.rotation.x = -Math.PI / 2;
axisGroup.add(axisTip);

/* image-plane overlay (flow view) */
const imgOverlay = new THREE.Group();
imgOverlay.visible = false;
activeGroup.add(imgOverlay);
const quad = new THREE.Mesh(
  new THREE.PlaneGeometry(RECT_W, RECT_H),
  new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.92, side: THREE.DoubleSide, depthWrite: false })
);
quad.position.set(0, MID_Y, 0.0015);
imgOverlay.add(quad);
registerInteractive(quad, {
  title: 'Image plane',
  tooltip: 'Where the scene is projected',
  body: 'Everything the camera records lives on this rectangle. A sideways translation T slides every projected point across it; a point at depth Z shifts by du = −f·Tx / Z.'
});

/* ── scene points, rays, projected dots, flow vectors ────────────────────── */
const PTS = [
  { P: new THREE.Vector3(0.28, 0.10, -1.0), color: 0xe07a00, name: 'near' },
  { P: new THREE.Vector3(-0.22, 0.22, -3.0), color: 0x1b7fc4, name: 'far' }
];
const flowGroup = new THREE.Group();
for (const q of PTS) {
  q.Zd = -q.P.z;
  q.perBaseline = F * SPACING / q.Zd;
  const mat = new THREE.MeshBasicMaterial({ color: q.color });
  const sph = new THREE.Mesh(new THREE.SphereGeometry(0.022, 16, 12), mat);
  sph.position.copy(q.P);
  flowGroup.add(sph);
  registerInteractive(sph, {
    title: (q.name === 'near' ? 'Near scene point  (Z = 1.0)' : 'Far scene point  (Z = 3.0)'),
    tooltip: 'Depth Z sets how fast it sweeps',
    body: 'For a pure lateral translation Tx the image point shifts by du = −f·Tx / Z. This point sits at Z = ' +
      q.Zd.toFixed(1) + ', so it slides ' + (q.name === 'near' ? '3× faster' : '3× slower') +
      ' across the image than the other one. That depth-dependent difference is motion parallax.'
  });

  const ray = new THREE.Line(
    new THREE.BufferGeometry().setFromPoints([q.P.clone(), q.P.clone()]),
    new THREE.LineBasicMaterial({ color: q.color, transparent: true, opacity: 0.6 })
  );
  flowGroup.add(ray);
  q.ray = ray;

  const dot = new THREE.Mesh(new THREE.SphereGeometry(0.010, 14, 10), mat);
  imgOverlay.add(dot);
  q.dot = dot;

  const len = FLOW_K / q.Zd;
  const hl = Math.min(0.028, len * 0.42);
  const am = new THREE.Mesh(arrowGeom(len, 0.009, hl, hl * 1.35, -1),
    new THREE.MeshBasicMaterial({ color: RED, side: THREE.DoubleSide }));
  imgOverlay.add(am);
  q.arrow = am;
  q.alen = len;
}

/* ── CAMERA: the printed, front-on figure pose ───────────────────────────── */
const FRONT_VIEW = { projection: 'orthographic', azimuthDeg: 90, elevationDeg: 0, heightFraction: 0.96 };
const FLOW_VIEW = { projection: 'orthographic', azimuthDeg: 102, elevationDeg: 14, zoom: 1.55, target: [0, 0.05, -0.75] };
setCameraView(FRONT_VIEW);

/* ── LABELS ──────────────────────────────────────────────────────────────── */
const tickLabels = CAM_I.map((i, k) =>
  addLabel((i > 0 ? '+' : '') + i + 'b', new THREE.Vector3(CAM_X[k], TOP_Y + 0.045, 0),
    { fontSize: '11px', color: '#777' }));

const lblT = addLabel('translation&nbsp;<b>T</b>&nbsp; ∥ image plane&nbsp; ( ⊥ optical axis )',
  new THREE.Vector3(0, -0.20, 0), { fontSize: '14px', color: '#c00000' });

const lblActive = addLabel('active camera', new THREE.Vector3(-1.56, 0.33, 0),
  { fontSize: '12px', color: '#1054a8', bold: true });
const lblAxis = addLabel('optical axis', new THREE.Vector3(-1.56, -0.01, -0.45),
  { fontSize: '11px', color: '#42708f', offset: [0, 14] });

const lblImg = addLabel('image plane', new THREE.Vector3(-1.56, TOP_Y + 0.05, 0.01), { fontSize: '11px', color: '#444' });
const lblNear = addLabel('near point&nbsp; Z = 1.0', PTS[0].P.clone().add(new THREE.Vector3(0, 0.07, 0)),
  { fontSize: '11px', color: '#b05e00' });
const lblFar = addLabel('far point&nbsp; Z = 3.0', PTS[1].P.clone().add(new THREE.Vector3(0, 0.07, 0)),
  { fontSize: '11px', color: '#14618f' });
const lblNearFlow = addLabel('', new THREE.Vector3(), { fontSize: '10px', color: '#c00000' });
const lblFarFlow = addLabel('', new THREE.Vector3(), { fontSize: '10px', color: '#c00000' });
const flowLabels = [lblImg, lblNear, lblFar, lblNearFlow, lblFarFlow];
function setLblVis(e, on) { e.div.style.visibility = on ? 'visible' : 'hidden'; }

/* ── STATE ───────────────────────────────────────────────────────────────── */
const state = { tx: -2, mode: 'path', annot: false, active: false };  // tx in baselines
let playing = false, tween = null, last = performance.now(), stepIdx = 0;

const slider = document.getElementById('slideCamera');
const txVal = document.getElementById('txVal');
const readout = document.getElementById('flowReadout');
const chkAnnot = document.getElementById('chkAnnot');
const btnPath = document.getElementById('modePath');
const btnFlow = document.getElementById('modeFlow');
const btnPlay = document.getElementById('playTranslation');
const stepTitle = document.getElementById('stepTitle');
const stepText = document.getElementById('stepText');

function applyVis() {
  const flow = state.mode === 'flow';
  trail.visible = state.annot;
  axisGroup.visible = state.annot && state.active;
  activeGroup.visible = state.active;
  imgOverlay.visible = flow && state.active;
  tickLabels.forEach(l => setLblVis(l, state.annot));
  setLblVis(lblT, !flow && state.annot);
  setLblVis(lblActive, state.active && state.annot);
  setLblVis(lblAxis, state.active && state.annot);
  flowLabels.forEach(l => setLblVis(l, flow && state.active));
  glyphs.forEach(g => { g.userData.mat.opacity = flow ? 0.16 : 1; });
  redMat.opacity = flow ? 0.20 : 1;
  slateMat.opacity = flow ? 0.35 : 0.85;
}

function updateFlow() {
  const wx = state.tx * SPACING;
  const Cw = new THREE.Vector3(wx, 0, 0);
  let txt = '';
  for (const q of PTS) {
    const u = F * (q.P.x - Cw.x) / q.Zd;
    const v = F * (q.P.y - Cw.y) / q.Zd;
    const lx = cl(u, -0.14, 0.14);
    const ly = MID_Y + cl(v, -0.048, 0.048);
    q.dot.position.set(lx, ly, 0.006);
    q.arrow.position.set(lx, ly, 0.008);
    q.ray.geometry.setFromPoints([q.P.clone(), Cw.clone()]);
    q.ray.geometry.computeBoundingSphere();
    const lbl = (q.name === 'near') ? lblNearFlow : lblFarFlow;
    lbl.pos.set(wx + lx - q.alen - 0.05, ly - 0.035, 0.012);
    lbl.div.innerHTML = '|du| = ' + q.perBaseline.toFixed(3) + ' / baseline';
    txt += (q.name === 'near' ? 'near' : 'far&nbsp;') + ' (Z = ' + q.Zd.toFixed(1) + '): u = ' +
      u.toFixed(3) + ', |du| = ' + q.perBaseline.toFixed(3) + ' per baseline<br>';
  }
  if (state.mode === 'flow') {
    const ratio = PTS[0].perBaseline / PTS[1].perBaseline;
    readout.innerHTML = '<b>du = &minus;f·T<sub>x</sub>/Z</b> &nbsp;(f = ' + F + ')<br>' + txt +
      '<b>near / far = ' + ratio.toFixed(1) + '×</b> — pure parallax, no looming.';
  }
}

function setTx(v, silent) {
  state.tx = cl(v, -2, 2);
  const wx = state.tx * SPACING;
  activeGroup.position.x = wx;
  slider.value = state.tx;
  txVal.textContent = state.tx.toFixed(2);
  lblActive.pos.set(wx, 0.33, 0);
  lblAxis.pos.set(wx + 0.09, -0.01, -0.45);
  lblImg.pos.set(wx - 0.12, TOP_Y + 0.05, 0.01);
  updateFlow();
  if (!silent && !state.active) { state.active = true; applyVis(); }
}

function setMode(m) {
  const changed = state.mode !== m;
  state.mode = m;
  const flow = (m === 'flow');
  if (flow && !flowGroup.parent) scene.add(flowGroup);
  if (!flow && flowGroup.parent) scene.remove(flowGroup);
  if (flow) state.active = true;
  btnPath.classList.toggle('active', !flow);
  btnFlow.classList.toggle('active', flow);
  applyVis();
  if (changed || !flow) setCameraView(flow ? FLOW_VIEW : FRONT_VIEW);
  if (!flow) readout.innerHTML = 'Front-on <b>figure view</b>. Switch to <i>Projected optical flow</i> to see how the image itself moves.';
  updateFlow();
}

function syncPlayBtn() {
  btnPlay.textContent = playing ? '❚❚ Pause' : '▶ Play lateral translation';
  btnPlay.classList.toggle('active', playing);
}

slider.addEventListener('input', () => {
  playing = false; tween = null; syncPlayBtn();
  setTx(parseFloat(slider.value));
});
btnPath.addEventListener('click', () => setMode('path'));
btnFlow.addEventListener('click', () => setMode('flow'));
chkAnnot.addEventListener('change', () => { state.annot = chkAnnot.checked; applyVis(); });
btnPlay.addEventListener('click', () => {
  playing = !playing; tween = null; syncPlayBtn();
  if (playing && !state.active) { state.active = true; applyVis(); }
});

/* ── animation ───────────────────────────────────────────────────────────── */
function tick() {
  requestAnimationFrame(tick);
  const now = performance.now();
  const dt = Math.min(0.05, (now - last) / 1000); last = now;
  if (playing) {
    let v = state.tx + 0.7 * dt;
    if (v > 2) v = -2;
    setTx(v, true);
  } else if (tween) {
    tween.t += dt;
    const k = Math.min(1, tween.t / tween.dur);
    const e = k * k * (3 - 2 * k);
    setTx(tween.from + (tween.to - tween.from) * e, true);
    if (k >= 1) tween = null;
  }
}
tick();

